(window.CARDS = window.CARDS || {}).place = [{"name":"Эйфелева башня","emoji":"🗼","meta":["Франция","металлическая башня","1889"],"description":"Ажурная металлическая башня на Марсовом поле в Париже, построенная для Всемирной выставки как временное сооружение и ставшая главным символом Франции. С трёх смотровых площадок открывается панорама города, а по вечерам башня вспыхивает огнями каждый час.","fact":"Пока башню строили, группа парижских художников и писателей публично протестовала против неё, называя сооружение уродливым и бесполезным.","wiki_en":"Eiffel Tower"},{"name":"Колизей","emoji":"🏟️","meta":["Италия","античный амфитеатр","I век н.э."],"description":"Крупнейший амфитеатр Древнего Рима, где проходили гладиаторские бои и представления с участием диких животных перед десятками тысяч зрителей. Несмотря на землетрясения и века разрушений, его арки и своды остаются одним из самых узнаваемых символов Италии.","fact":"Под ареной сохранился лабиринт подземных коридоров — гипогей, где держали гладиаторов и животных перед выходом на арену.","wiki_en":"Colosseum"},{"name":"Статуя Свободы","emoji":"🗽","meta":["США","статуя","1886"],"description":"Гигантская статуя женщины с факелом на острове в Нью-Йоркской гавани, подаренная Францией в знак дружбы между странами. Она стала символом свободы и надежды для миллионов иммигрантов, прибывавших в Америку морем.","fact":"Внешняя оболочка статуи собрана из тонких медных листов: они со временем окислились и дали ей узнаваемый зеленоватый цвет.","wiki_en":"Statue of Liberty"},{"name":"Великая Китайская стена","emoji":"🧱","meta":["Китай","оборонительная стена","века до н.э. — XVII век"],"description":"Растянувшаяся на тысячи километров цепь стен, башен и укреплений, которую строили и перестраивали разные китайские династии для защиты от набегов кочевников. Сегодня это крупнейший рукотворный памятник в мире и один из символов Китая.","fact":"Вопреки популярному мифу, стену невозможно разглядеть невооружённым глазом с орбиты Земли.","wiki_en":"Great Wall of China"},{"name":"Тадж-Махал","emoji":"🤍","meta":["Индия","мавзолей","XVII век"],"description":"Беломраморный мавзолей в Агре, который падишах Шах-Джахан построил в память о своей любимой жене Мумтаз-Махал. Его симметричные купола, минареты и инкрустация полудрагоценными камнями считаются вершиной могольской архитектуры.","fact":"Цвет мрамора Тадж-Махала меняется в течение дня — от розоватого на рассвете до золотистого на закате.","wiki_en":"Taj Mahal"},{"name":"Мачу-Пикчу","emoji":"🏔️","meta":["Перу","город инков","XV век"],"description":"Затерянный в Андах горный город инков, построенный из тщательно подогнанных каменных блоков без раствора. Долгое время он был неизвестен внешнему миру и хорошо сохранился именно потому, что испанские конкистадоры его так и не нашли.","fact":"Точное предназначение Мачу-Пикчу остаётся предметом споров: его считают то летней резиденцией правителя, то святилищем.","wiki_en":"Machu Picchu"},{"name":"Пирамиды Гизы","emoji":"🔺","meta":["Египет","древние пирамиды","около 2500 года до н.э."],"description":"Комплекс монументальных гробниц египетских фараонов на плато к западу от Каира, самая известная из которых — пирамида Хеопса. Долгие века она оставалась самым высоким сооружением, построенным человеком.","fact":"Пирамиды Гизы — единственное из семи чудес древнего мира, сохранившееся до наших дней почти целиком.","wiki_en":"Giza pyramid complex"},{"name":"Большой сфинкс","emoji":"🦁","meta":["Египет","статуя со львиным телом","около 2500 года до н.э."],"description":"Исполинская статуя с телом льва и головой человека, вырезанная из известнякового останца рядом с пирамидами Гизы. Считается, что лицо изображает одного из египетских фараонов, хотя единого мнения об этом у учёных нет.","fact":"У Сфинкса отсутствует нос, и одна из легенд приписывает его утрату пушечному выстрелу солдат Наполеона, хотя повреждение старше этой истории.","wiki_en":"Great Sphinx of Giza"},{"name":"Петра","emoji":"🏜️","meta":["Иордания","город, высеченный в скале","около IV века до н.э."],"description":"Древняя столица набатейского царства, чьи храмы и гробницы высечены прямо в розовато-красных скалах пустыни. К самому знаменитому фасаду — Эль-Хазне — ведёт узкое ущелье Сик длиной около километра.","fact":"Петру называют «розовым городом» за характерный цвет песчаника, из которого высечены её фасады.","wiki_en":"Petra"},{"name":"Статуя Христа-Искупителя","emoji":"✝️","meta":["Бразилия","статуя","1931"],"description":"Монументальная статуя Иисуса Христа с раскинутыми руками на вершине горы Корковаду над Рио-де-Жанейро. Она видна практически из любой точки города и стала одним из самых узнаваемых символов Бразилии.","fact":"Из-за высоты горы статуя нередко оказывается в облаках, и туристам приходится ждать, пока они рассеются.","wiki_en":"Christ the Redeemer (statue)"},{"name":"Чичен-Ица","emoji":"🐍","meta":["Мексика","город майя","около IX века"],"description":"Один из крупнейших городов цивилизации майя на полуострове Юкатан, центром которого служит ступенчатая пирамида Кукулькана. В дни весеннего и осеннего равноденствия на её ступенях возникает игра света и тени, похожая на спускающуюся змею.","fact":"Если хлопнуть в ладоши перед пирамидой Кукулькана, эхо отражается звуком, похожим на крик священной птицы кетцаль.","wiki_en":"Chichen Itza"},{"name":"Ангкор-Ват","emoji":"🛕","meta":["Камбоджа","храмовый комплекс","XII век"],"description":"Крупнейший в мире религиозный комплекс, построенный кхмерскими правителями сначала как индуистский храм, а позже ставший буддийским святилищем. Его пять башен, напоминающих бутоны лотоса, изображены даже на государственном флаге Камбоджи.","fact":"Ангкор-Ват окружён рвом шириной почти двести метров, который защищал храм и одновременно стабилизировал фундамент здания.","wiki_en":"Angkor Wat"},{"name":"Саграда Фамилия","emoji":"⛪","meta":["Испания","базилика","с 1882 года"],"description":"Огромная базилика в Барселоне, спроектированная архитектором Антонио Гауди в его неповторимом стиле, где башни напоминают оплавленный воск и песочные фигуры. Строительство началось в конце XIX века и до сих пор не завершено.","fact":"Гауди говорил, что у его заказчика — Бога — не бывает спешки, поэтому не рассчитывал увидеть здание законченным при жизни.","wiki_en":"Sagrada Família"},{"name":"Биг-Бен","emoji":"🕰️","meta":["Великобритания","часовая башня","1859"],"description":"Башня Елизаветы при Вестминстерском дворце в Лондоне, чьи куранты и главный колокол давно известны публике под именем Биг-Бен. Бой этих часов транслируют по радио и телевидению как звуковой символ Британии.","fact":"Строго говоря, «Биг-Бен» — имя не башни и не часов, а самого большого колокола внутри неё.","wiki_en":"Big Ben"},{"name":"Тауэрский мост","emoji":"🌉","meta":["Великобритания","разводной мост","1894"],"description":"Мост через Темзу рядом с лондонским Тауэром, чьи две высокие башни соединены пешеходными галереями. Центральная часть моста поднимается, пропуская высокие суда, — редкое зрелище, которое до сих пор собирает зевак.","fact":"Издалека Тауэрский мост часто путают с Лондонским мостом, хотя это два совершенно разных сооружения.","wiki_en":"Tower Bridge"},{"name":"Букингемский дворец","emoji":"👑","meta":["Великобритания","королевский дворец","с 1837 года"],"description":"Официальная лондонская резиденция британских монархов, где проходят государственные приёмы и церемония смены караула. Когда монарх находится во дворце, над крышей поднимают королевский штандарт.","fact":"Во дворце сотни комнат, включая собственный кинозал, бассейн и почтовое отделение.","wiki_en":"Buckingham Palace"},{"name":"Стоунхендж","emoji":"🪨","meta":["Великобритания","мегалитическое сооружение","около 2500 года до н.э."],"description":"Кольцо исполинских каменных глыб в английской равнине Солсбери, возведённое ещё в доисторические времена, задолго до появления в Британии металлических инструментов. Точное назначение памятника — храм, обсерватория или место погребений — остаётся предметом споров.","fact":"Некоторые камни Стоунхенджа привезены с валлийских холмов, расположенных за много десятков километров от равнины.","wiki_en":"Stonehenge"},{"name":"Лувр","emoji":"🖼️","meta":["Франция","музей","открыт в 1793 году"],"description":"Крупнейший художественный музей мира, разместившийся в бывшем королевском дворце в центре Парижа. В его коллекции хранится «Джоконда» Леонардо да Винчи и тысячи других шедевров искусства разных эпох.","fact":"Стеклянная пирамида во дворе Лувра, ставшая символом музея, появилась только в конце XX века и поначалу вызвала бурные споры.","wiki_en":"Louvre"},{"name":"Собор Парижской Богоматери","emoji":"🔔","meta":["Франция","готический собор","XII–XIV века"],"description":"Собор на острове Сите в центре Парижа — один из первых и самых значимых памятников готической архитектуры Европы. Его прославил одноимённый роман Виктора Гюго о звонаре Квазимодо.","fact":"После пожара 2019 года, серьёзно повредившего крышу и шпиль, собор восстанавливали несколько лет по историческим технологиям.","wiki_en":"Notre-Dame de Paris"},{"name":"Триумфальная арка","emoji":"🏛️","meta":["Франция","триумфальная арка","1836"],"description":"Монументальная арка на площади Шарля де Голля в Париже, заложенная по приказу Наполеона в честь побед французской армии. От неё лучами расходятся двенадцать проспектов, включая Елисейские поля.","fact":"Под аркой находится могила Неизвестного солдата с вечным огнём, который не гаснет с 1920-х годов.","wiki_en":"Arc de Triomphe"},{"name":"Версаль","emoji":"🪞","meta":["Франция","королевский дворец","XVII век"],"description":"Гигантский дворцово-парковый ансамбль под Парижем, превращённый Людовиком XIV из охотничьего замка в главную резиденцию французских королей. Зеркальная галерея и регулярные сады стали образцом для подражания по всей Европе.","fact":"Именно в Зеркальной галерее Версаля в 1919 году подписали договор, официально завершивший Первую мировую войну.","wiki_en":"Palace of Versailles"},{"name":"Мон-Сен-Мишель","emoji":"🏝️","meta":["Франция","остров-аббатство","Средние века"],"description":"Скалистый остров у побережья Нормандии, увенчанный средневековым аббатством, шпиль которого виден за много километров. Во время сильных приливов вода отрезает остров от материка, превращая его в настоящую крепость.","fact":"Приливы у Мон-Сен-Мишеля — одни из самых больших в Европе, и разница уровня воды может достигать высоты многоэтажного дома.","wiki_en":"Mont-Saint-Michel"},{"name":"Пизанская башня","emoji":"📐","meta":["Италия","колокольня","XII–XIV века"],"description":"Отдельно стоящая колокольня собора в Пизе, которая начала крениться ещё во время строительства из-за мягкого грунта под фундаментом. Именно этот дефект превратил башню из рядовой колокольни в одну из самых узнаваемых достопримечательностей мира.","fact":"Наклон башни в разные годы пытались остановить и даже немного выправить с помощью подземных грузов и укрепления фундамента.","wiki_en":"Leaning Tower of Pisa"},{"name":"Фонтан Треви","emoji":"🪙","meta":["Италия","фонтан","1762"],"description":"Самый большой и знаменитый фонтан Рима, украшенный скульптурами морских божеств на фоне дворцового фасада. По традиции туристы бросают в его воду монетку через плечо, чтобы однажды вернуться в город.","fact":"Каждый день из фонтана вычерпывают тысячи брошенных монет, а собранные деньги идут на благотворительность.","wiki_en":"Trevi Fountain"},{"name":"Пантеон в Риме","emoji":"🕳️","meta":["Италия","античный храм","II век н.э."],"description":"Один из наиболее хорошо сохранившихся храмов Древнего Рима с гигантским куполом, в центре которого оставлено круглое отверстие — окулус. Через него в здание льётся дневной свет, а в дождь вода стекает по специально продуманному наклону пола.","fact":"Почти две тысячи лет спустя купол Пантеона всё ещё остаётся крупнейшим в мире куполом из неармированного бетона.","wiki_en":"Pantheon, Rome"},{"name":"Собор Святого Петра","emoji":"🕊️","meta":["Ватикан","базилика","XVI–XVII века"],"description":"Крупнейший католический храм мира, стоящий на месте, где по преданию похоронен апостол Пётр. Над его куполом работал Микеланджело, а площадь перед собором окружена колоннадой Бернини.","fact":"Купол собора Святого Петра остаётся одним из самых высоких в мире, и подняться на него можно пешком по узкой внутренней лестнице.","wiki_en":"St. Peter's Basilica"},{"name":"Помпеи","emoji":"🌋","meta":["Италия","античный город","разрушен в 79 году н.э."],"description":"Римский город, погребённый под пеплом и пемзой при извержении Везувия и благодаря этому сохранившийся почти нетронутым до наших дней. Раскопки открыли улицы, дома и фрески, которые дают редкую возможность увидеть повседневную жизнь древних римлян.","fact":"Пустоты, оставшиеся в затвердевшем пепле от тел погибших, археологи заполняют гипсом, получая точные слепки людей в момент катастрофы.","wiki_en":"Pompeii"},{"name":"Парфенон","emoji":"🏺","meta":["Греция","античный храм","V век до н.э."],"description":"Главный храм афинского Акрополя, посвящённый богине Афине и построенный в эпоху расцвета классической Греции. Его пропорции и колоннада стали эталоном для архитектуры на тысячелетия вперёд.","fact":"Многие скульптуры и фризы Парфенона хранятся сегодня в Британском музее в Лондоне, что остаётся предметом давнего спора между Грецией и Великобританией.","wiki_en":"Parthenon"},{"name":"Айя-София","emoji":"🕌","meta":["Турция","храм-мечеть","VI век"],"description":"Величественное сооружение в Стамбуле, построенное как христианский собор, столетия служившее мечетью, затем музеем, а ныне снова действующее как мечеть. Его гигантский купол долгое время оставался крупнейшим в мире.","fact":"Внутри здания до сих пор можно увидеть и христианские мозаики, и исламскую каллиграфию, соседствующие в одном пространстве.","wiki_en":"Hagia Sophia"},{"name":"Голубая мечеть","emoji":"🔷","meta":["Турция","мечеть","XVII век"],"description":"Стамбульская мечеть султана Ахмеда, получившая своё неофициальное название за тысячи голубых изникских изразцов, украшающих интерьер. Она построена напротив Айя-Софии и во многом вступает с ней в архитектурный диалог.","fact":"Голубая мечеть — одна из немногих в мире, у которой изначально было построено шесть минаретов, что в своё время вызвало споры.","wiki_en":"Sultan Ahmed Mosque"},{"name":"Каппадокия","emoji":"🎈","meta":["Турция","скальный регион","формировалась миллионы лет"],"description":"Область в центральной Турции с причудливыми скальными образованиями — «каминами фей», — а также подземными городами и пещерными храмами, высеченными в вулканическом туфе. Сегодня она знаменита ещё и полётами на воздушных шарах на рассвете.","fact":"В Каппадокии сохранились целые подземные города, где жители укрывались от набегов, вырубая многоуровневые тоннели прямо в мягком туфе.","wiki_en":"Cappadocia"},{"name":"Памуккале","emoji":"⚪","meta":["Турция","известковые террасы","формировались тысячелетиями"],"description":"Белоснежные травертиновые террасы на юго-западе Турции, образованные минеральными горячими источниками. Название переводится как «хлопковый замок» — именно так выглядят застывшие ступени с бирюзовой водой.","fact":"Рядом с Памуккале сохранились руины античного города Иераполя, жители которого веками пользовались теми же горячими источниками.","wiki_en":"Pamukkale"},{"name":"Бурдж-Халифа","emoji":"🏙️","meta":["ОАЭ","небоскрёб","2010"],"description":"Самое высокое здание в мире, возвышающееся над Дубаем и видимое за десятки километров в ясную погоду. Его форма, сужающаяся к вершине, вдохновлена силуэтом пустынного цветка гименокаллис.","fact":"На верхних этажах Бурдж-Халифы закат можно наблюдать на несколько минут дольше, чем у подножия здания.","wiki_en":"Burj Khalifa"},{"name":"Мечеть шейха Зайда","emoji":"🕌","meta":["ОАЭ","мечеть","2007"],"description":"Огромная белоснежная мечеть в Абу-Даби с десятками куполов и минаретов, отделанная мрамором и украшенная одним из крупнейших в мире ручных ковров. Она названа в честь первого президента страны и открыта для посещения людьми разных религий.","fact":"Главный молитвенный зал мечети украшают гигантские люстры с кристаллами Swarovski, одни из крупнейших в мире.","wiki_en":"Sheikh Zayed Grand Mosque"},{"name":"Стена Плача","emoji":"🙏","meta":["Израиль","сохранившаяся стена Храмовой горы","древность"],"description":"Западная подпорная стена Храмовой горы в Иерусалиме, оставшаяся от комплекса Второго Иерусалимского храма. Для иудеев это самое святое место для молитвы, куда веками приходят оплакивать разрушение храма.","fact":"В щели между камнями Стены Плача принято вкладывать записки с молитвами и просьбами, адресованными Богу.","wiki_en":"Western Wall"},{"name":"Купол Скалы","emoji":"🟡","meta":["Израиль","исламское святилище","VII век"],"description":"Золотокупольное святилище на Храмовой горе в Иерусалиме, один из старейших сохранившихся памятников исламской архитектуры. По преданию, здесь пророк Мухаммед вознёсся на небеса во время ночного путешествия.","fact":"Золотое покрытие купола — сравнительно недавнее обновление XX века, а изначально купол был обшит другими материалами.","wiki_en":"Dome of the Rock"},{"name":"Мёртвое море","emoji":"🧂","meta":["Израиль и Иордания","солёное озеро","природный объект"],"description":"Бессточное озеро между Израилем и Иорданией с одной из самых высоких концентраций соли на Земле, из-за которой в его воде почти невозможно погрузиться — тело само выталкивает на поверхность. Его берега — самая низкая точка суши на планете.","fact":"Из-за интенсивного забора воды уровень Мёртвого моря постепенно снижается, и берег из года в год отступает.","wiki_en":"Dead Sea"},{"name":"Красная площадь","emoji":"🟥","meta":["Россия","главная площадь Москвы","XV век"],"description":"Центральная площадь Москвы у стен Кремля, на протяжении веков служившая местом торговли, парадов и главных исторических событий страны. Своё название она получила задолго до советской эпохи — слово «красная» когда-то означало «красивая».","fact":"Историческое название площади не связано с цветом кремлёвских стен или советской символикой, вопреки расхожему заблуждению.","wiki_en":"Red Square"},{"name":"Храм Василия Блаженного","emoji":"🧅","meta":["Россия","собор","XVI век"],"description":"Собор Покрова Пресвятой Богородицы на Красной площади, построенный по приказу Ивана Грозного в честь взятия Казани. Его разноцветные узорчатые купола не имеют аналогов и давно стали визуальным символом Москвы.","fact":"Ни одна из девяти глав храма не повторяет узор другой — все купола расписаны по-разному.","wiki_en":"Saint Basil's Cathedral"},{"name":"Московский Кремль","emoji":"⭐","meta":["Россия","крепость и резиденция власти","XV век"],"description":"Древняя крепость в центре Москвы с краснокирпичными стенами и башнями, за которыми находятся соборы, дворцы и резиденция президента России. Кремль остаётся действующим центром государственной власти на протяжении веков.","fact":"Рубиновые звёзды на кремлёвских башнях сменили двуглавых орлов только в 1930-х годах.","wiki_en":"Moscow Kremlin"},{"name":"Эрмитаж","emoji":"🎨","meta":["Россия","музей","1764"],"description":"Один из крупнейших художественных музеев мира, разместившийся в Зимнем дворце и соседних зданиях на набережной Невы в Санкт-Петербурге. Его коллекция началась с частного собрания картин императрицы Екатерины II.","fact":"Если бы посетитель уделял каждому экспонату Эрмитажа хотя бы минуту, на осмотр всей коллекции ушли бы годы.","wiki_en":"Hermitage Museum"},{"name":"Петергоф","emoji":"⛲","meta":["Россия","дворцово-парковый ансамбль","XVIII век"],"description":"Загородная резиденция русских императоров под Санкт-Петербургом, знаменитая каскадами фонтанов, работающими без единого насоса — только за счёт естественного перепада высот. Её называют «русским Версалем», хотя Пётр I задумывал ансамбль как самостоятельный шедевр.","fact":"В парке спрятаны фонтаны-шутихи: они неожиданно окатывают водой того, кто наступит на скрытый камень или подойдёт слишком близко.","wiki_en":"Peterhof Palace"},{"name":"Спас на Крови","emoji":"🖌️","meta":["Россия","собор","начало XX века"],"description":"Нарядный собор в Санкт-Петербурге, построенный на месте смертельного ранения императора Александра II в память о нём. Его фасады и купола в русском стиле резко выделяются среди строгой архитектуры центра города, а интерьер почти целиком покрыт мозаикой.","fact":"Мозаики покрывают внутри собора несколько тысяч квадратных метров — это одно из крупнейших собраний мозаики в Европе.","wiki_en":"Church of the Savior on Blood"},{"name":"Кижи","emoji":"🪵","meta":["Россия","музей деревянного зодчества","XVIII век"],"description":"Остров на Онежском озере в Карелии, известный ансамблем деревянных церквей, срубленных без единого гвоздя. Главная из них, двадцатидвуглавая Преображенская церковь, — вершина русского плотницкого мастерства.","fact":"По легенде, построивший Преображенскую церковь мастер забросил свой топор в озеро, сказав, что такой больше не построит никто.","wiki_en":"Kizhi Pogost"},{"name":"Озеро Байкал","emoji":"🌊","meta":["Россия","озеро","природный объект"],"description":"Самое глубокое озеро планеты в самом сердце Сибири, хранящее огромную долю мировых запасов пресной воды. Вода в нём настолько прозрачна, что в некоторых местах дно видно на десятки метров вглубь.","fact":"В Байкале обитает нерпа — один из немногих в мире видов тюленей, живущих исключительно в пресной воде.","wiki_en":"Lake Baikal"},{"name":"Родина-мать зовёт!","emoji":"⚔️","meta":["Россия","монумент","1967"],"description":"Гигантская статуя женщины с поднятым мечом на Мамаевом кургане в Волгограде, посвящённая победе в Сталинградской битве. Долгое время она считалась самой высокой статуей в мире.","fact":"Меч монумента настолько велик и подвержен ветровым нагрузкам, что его конструкцию несколько раз укрепляли и меняли материал полотна.","wiki_en":"The Motherland Calls"},{"name":"Эльбрус","emoji":"⛰️","meta":["Россия","гора","потухший вулкан"],"description":"Двуглавая гора на Кавказе, считающаяся самой высокой точкой Европы, хотя вопрос о принадлежности к части света остаётся предметом споров географов. Это потухший вулкан, чьи склоны покрыты ледниками круглый год.","fact":"Эльбрус входит в список «Семь вершин» — высочайших гор каждой части света, популярный среди альпинистов маршрут восхождений.","wiki_en":"Mount Elbrus"},{"name":"Бранденбургские ворота","emoji":"🚪","meta":["Германия","триумфальные ворота","XVIII век"],"description":"Монументальные ворота в центре Берлина, увенчанные колесницей богини победы, которые десятилетиями стояли почти на границе Западного и Восточного Берлина. Сегодня они — символ объединения Германии и мирного падения Берлинской стены.","fact":"Во время холодной войны ворота были фактически недоступны для прохода и стали одним из самых узнаваемых символов раскола Германии.","wiki_en":"Brandenburg Gate"},{"name":"Замок Нойшванштайн","emoji":"🏰","meta":["Германия","замок","XIX век"],"description":"Сказочный замок в баварских Альпах, построенный по заказу эксцентричного короля Людвига II как воплощение его романтических фантазий. Именно этот замок вдохновил архитекторов Диснея на создание знаменитого замка Спящей красавицы.","fact":"Людвиг II успел прожить в замке лишь считаные месяцы до своей загадочной смерти, так и не увидев здание полностью завершённым.","wiki_en":"Neuschwanstein Castle"},{"name":"Кёльнский собор","emoji":"⛪","meta":["Германия","готический собор","строился с XIII века"],"description":"Один из самых высоких готических соборов Европы, чьи ажурные шпили доминируют над центром Кёльна. Его строительство растянулось на столетия и было приостановлено на долгий период, прежде чем возобновилось и завершилось уже в XIX веке.","fact":"Собор выстоял в бомбардировках Второй мировой войны, хотя и получил повреждения, а окружавший его центр Кёльна был разрушен почти полностью.","wiki_en":"Cologne Cathedral"},{"name":"Карлов мост","emoji":"🚶","meta":["Чехия","мост","XIV век"],"description":"Старинный каменный мост через Влтаву в Праге, украшенный рядом статуй святых и ведущий от Старого города к Пражскому Граду. Днём и ночью он остаётся одним из самых оживлённых пешеходных мест столицы.","fact":"По легенде, в раствор для кладки моста добавляли яичные желтки, чтобы сделать конструкцию прочнее.","wiki_en":"Charles Bridge"},{"name":"Дворец Шёнбрунн","emoji":"🌳","meta":["Австрия","императорский дворец","XVIII век"],"description":"Летняя резиденция австрийских Габсбургов в Вене с роскошными интерьерами и регулярным парком, включающим один из старейших в мире зоопарков. Здесь прошли детские годы Марии-Антуанетты и юного Моцарта, выступавшего перед императрицей.","fact":"Зоопарк на территории Шёнбрунна был основан ещё в XVIII веке и считается старейшим из непрерывно действующих зоопарков мира.","wiki_en":"Schönbrunn Palace"},{"name":"Альгамбра","emoji":"🔶","meta":["Испания","дворцово-крепостной комплекс","XIII–XIV века"],"description":"Мавританская крепость и дворцовый комплекс на холме над Гранадой, построенный последней мусульманской династией на Пиренейском полуострове. Его резные арки, изразцы и тихие внутренние дворы с фонтанами считаются вершиной исламского искусства в Европе.","fact":"После падения Гранады в 1492 году Альгамбра досталась испанским королям, и позже часть комплекса перестроили в ренессансный дворец Карла V.","wiki_en":"Alhambra"},{"name":"Парк Гуэль","emoji":"🦎","meta":["Испания","парк","начало XX века"],"description":"Причудливый парк в Барселоне, спроектированный Антонио Гауди с извилистыми скамейками, мозаичными террасами и сказочными домиками у входа. Изначально его задумывали как элитный жилой квартал, но идея не прижилась, и территорию превратили в общественный парк.","fact":"Мозаичная ящерица у главного входа в парк стала одним из самых узнаваемых и часто фотографируемых символов Барселоны.","wiki_en":"Park Güell"},{"name":"Маттерхорн","emoji":"🍫","meta":["Швейцария и Италия","гора","природный объект"],"description":"Одна из самых узнаваемых по силуэту гор Альп с почти симметричной пирамидальной вершиной на границе Швейцарии и Италии. Именно эта форма вдохновила логотип шоколада Toblerone.","fact":"Первое успешное восхождение на Маттерхорн в XIX веке закончилось трагедией — при спуске погибла часть участников экспедиции.","wiki_en":"Matterhorn"},{"name":"Гейрангер-фьорд","emoji":"⛴️","meta":["Норвегия","фьорд","природный объект"],"description":"Один из самых живописных фьордов Норвегии, окружённый отвесными скалами с многочисленными водопадами, включая знаменитый каскад «Семь сестёр». Летом сюда заходят огромные круизные лайнеры, лавирующие между узкими берегами.","fact":"Фьорд образовался в результате движения ледников, оставивших после себя глубокую извилистую долину, впоследствии затопленную морем.","wiki_en":"Geirangerfjord"},{"name":"Скалы Мохер","emoji":"🐦","meta":["Ирландия","прибрежные скалы","природный объект"],"description":"Отвесные скалы на западном побережье Ирландии, обрывающиеся в Атлантический океан с высоты более двухсот метров. В хорошую погоду отсюда видны Аранские острова и горы соседних графств.","fact":"На уступах скал Мохер гнездятся тысячи морских птиц, включая колонии тупиков — маленьких птиц с ярким клювом.","wiki_en":"Cliffs of Moher"},{"name":"Эдинбургский замок","emoji":"🛡️","meta":["Великобритания","крепость","Средние века"],"description":"Средневековая крепость на вершине потухшего вулкана в центре Эдинбурга, веками служившая королевской резиденцией и военным укреплением. Сегодня здесь хранятся королевские регалии Шотландии, а со стен по сей день стреляет пушка, по которой горожане сверяли часы.","fact":"Каждый день, кроме воскресенья, из замка ровно в час дня стреляет пушка — традиция, заведённая ещё для моряков в гавани.","wiki_en":"Edinburgh Castle"},{"name":"Лох-Несс","emoji":"🦕","meta":["Великобритания","озеро","природный объект"],"description":"Длинное узкое озеро в Шотландском нагорье, знаменитое легендой о таинственном чудовище Несси, которое якобы обитает в его тёмных водах. Несмотря на десятилетия поисков и экспедиций, научных доказательств существования монстра так и не нашли.","fact":"Из-за большого количества торфа вода в Лох-Нессе очень тёмная, что сильно затрудняет любые подводные наблюдения.","wiki_en":"Loch Ness"},{"name":"Мост Золотые Ворота","emoji":"🌁","meta":["США","подвесной мост","1937"],"description":"Ярко-оранжевый подвесной мост через пролив у входа в бухту Сан-Франциско, долгое время остававшийся самым длинным висячим мостом в мире. Он нередко скрывается в густом тумане, что делает его ещё более узнаваемым.","fact":"Цвет моста официально называется «международный оранжевый» и был выбран отчасти потому, что он хорошо заметен в тумане.","wiki_en":"Golden Gate Bridge"},{"name":"Знак Голливуда","emoji":"🎬","meta":["США","надпись на склоне холма","1923"],"description":"Огромные белые буквы на холме над Лос-Анджелесом, изначально поставленные как реклама жилого района и позже превратившиеся в символ всей киноиндустрии США. Каждая буква высотой с несколько этажей видна из многих районов города.","fact":"Первоначально надпись гласила «HOLLYWOODLAND» — последние четыре буквы убрали только спустя несколько десятилетий.","wiki_en":"Hollywood Sign"},{"name":"Гранд-Каньон","emoji":"🏜️","meta":["США","каньон","формировался миллионы лет"],"description":"Гигантское ущелье, прорезанное рекой Колорадо в плато на юго-западе США, обнажившее слои горных пород возрастом в сотни миллионов лет. Его размеры настолько велики, что противоположный край каньона порой едва различим в дымке.","fact":"Слои разноцветных пород на стенах каньона позволяют геологам буквально читать историю Земли, как страницы книги.","wiki_en":"Grand Canyon"},{"name":"Йеллоустон","emoji":"♨️","meta":["США","национальный парк","1872"],"description":"Первый в мире национальный парк, знаменитый гейзерами, горячими источниками и супервулканом, дремлющим под его территорией. Самый известный гейзер парка, Old Faithful, извергается с достаточно предсказуемой регулярностью.","fact":"Под Йеллоустоном находится один из крупнейших действующих супервулканов планеты, хотя учёные не ожидают его извержения в обозримом будущем.","wiki_en":"Yellowstone National Park"},{"name":"Ниагарский водопад","emoji":"💦","meta":["США и Канада","водопад","природный объект"],"description":"Система из трёх мощных водопадов на границе США и Канады, включая знаменитую подкову — крупнейшую из них по объёму падающей воды. Ночью водопады подсвечивают цветными прожекторами, а летом вокруг них курсируют прогулочные катера.","fact":"Первым человеком, пережившим падение с Ниагарского водопада в бочке, стала пожилая школьная учительница в начале XX века.","wiki_en":"Niagara Falls"},{"name":"Гора Рашмор","emoji":"🪨","meta":["США","скульптурный монумент","1941"],"description":"Гранитная скала в Южной Дакоте, в которую вырезаны исполинские лица четырёх президентов США — Вашингтона, Джефферсона, Рузвельта и Линкольна. Над монументом больше десяти лет трудились сотни рабочих, спускавшихся к лицам в люльках на тросах.","fact":"Изначально планировалось изобразить президентов по пояс, но проект пришлось ограничить только лицами из-за нехватки средств.","wiki_en":"Mount Rushmore"},{"name":"Эмпайр-стейт-билдинг","emoji":"🦍","meta":["США","небоскрёб","1931"],"description":"Небоскрёб в стиле ар-деко на Манхэттене, который десятилетиями оставался самым высоким зданием мира. Его смотровые площадки на верхних этажах и сегодня остаются одной из самых популярных точек обзора Нью-Йорка.","fact":"Именно на шпиле Эмпайр-стейт-билдинг держал в лапе Кинг-Конг в знаменитом фильме 1933 года.","wiki_en":"Empire State Building"},{"name":"Таймс-сквер","emoji":"🎇","meta":["США","площадь","начало XX века"],"description":"Оживлённый перекрёсток на Манхэттене, облепленный гигантскими светящимися рекламными экранами и окружённый театрами Бродвея. Каждый год именно здесь тысячи людей встречают Новый год, наблюдая за спуском светящегося шара.","fact":"Название площади происходит от газеты The New York Times, чья редакция когда-то располагалась в здании на этом месте.","wiki_en":"Times Square"},{"name":"Центральный парк","emoji":"🍂","meta":["США","городской парк","1858"],"description":"Огромный зелёный прямоугольник посреди плотной застройки Манхэттена, спроектированный как место отдыха для жителей растущего мегаполиса. В парке есть озёра, луга, зоопарк и множество мест, знакомых зрителям по десяткам голливудских фильмов.","fact":"Центральный парк был одним из первых крупных ландшафтных парков, спроектированных специально, а не выросших вокруг существующего природного объекта.","wiki_en":"Central Park"},{"name":"Бруклинский мост","emoji":"🚴","meta":["США","подвесной мост","1883"],"description":"Один из старейших подвесных мостов Америки, соединяющий Манхэттен и Бруклин через Ист-Ривер. Его каменные неоготические башни и паутина стальных тросов на момент постройки поражали воображение как инженерное чудо.","fact":"Строительство моста заняло более десяти лет и стоило жизни нескольким десяткам рабочих, включая самого инженера проекта.","wiki_en":"Brooklyn Bridge"},{"name":"Белый дом","emoji":"🦅","meta":["США","резиденция президента","1800"],"description":"Официальная резиденция и рабочее место президента США в Вашингтоне, узнаваемая по белому неоклассическому фасаду. Здание не раз перестраивали после пожара во время войны 1812 года, но исторический облик и название сохранились.","fact":"Название «Белый дом» официально закрепилось только в начале XX века, хотя неформально его так называли задолго до этого.","wiki_en":"White House"},{"name":"Лас-Вегас-Стрип","emoji":"🎰","meta":["США","улица казино и отелей","XX век"],"description":"Знаменитый отрезок бульвара в Лас-Вегасе, застроенный гигантскими казино-отелями с тематическим оформлением — от египетских пирамид до венецианских каналов. Ночью улица превращается в море неоновой рекламы, ставшее визитной карточкой города.","fact":"Многие из знаменитых отелей Стрип не раз сносили и отстраивали заново, чтобы удивить публику ещё более масштабными аттракционами.","wiki_en":"Las Vegas Strip"},{"name":"Долина монументов","emoji":"🌵","meta":["США","плато с останцами","формировалось миллионы лет"],"description":"Пустынное плато на границе Аризоны и Юты, известное силуэтами гигантских песчаниковых останцов, обточенных ветром и водой за миллионы лет. Эти пейзажи узнаваемы по десяткам вестернов и рекламных роликов.","fact":"Долина монументов находится на территории резервации навахо и управляется самими навахо, а не национальной службой парков США.","wiki_en":"Monument Valley"},{"name":"Алькатрас","emoji":"⛓️","meta":["США","бывшая тюрьма на острове","закрыта в 1963 году"],"description":"Скалистый остров в бухте Сан-Франциско, где десятилетиями располагалась федеральная тюрьма строгого режима для самых опасных заключённых. Считалось, что холодные течения вокруг острова делают побег практически невозможным.","fact":"Ни один официально подтверждённый побег с Алькатраса не увенчался успехом, хотя судьба нескольких беглецов так и осталась невыясненной.","wiki_en":"Alcatraz Island"},{"name":"Си-Эн Тауэр","emoji":"🗼","meta":["Канада","телебашня","1976"],"description":"Высокая телекоммуникационная башня в центре Торонто, долгое время считавшаяся самым высоким отдельно стоящим сооружением в мире. На одном из верхних уровней у неё есть смотровая площадка со стеклянным полом.","fact":"Стоя на стеклянном полу смотровой площадки, можно увидеть улицу далеко внизу — многие посетители решаются встать на него не сразу.","wiki_en":"CN Tower"},{"name":"Водопады Игуасу","emoji":"🦋","meta":["Аргентина и Бразилия","система водопадов","природный объект"],"description":"Каскад из нескольких сотен отдельных водопадов на границе Аргентины и Бразилии, растянувшийся на несколько километров вдоль реки. Центральная и самая мощная часть системы носит название «Глотка дьявола».","fact":"Водопады Игуасу шире и в определённом смысле масштабнее знаменитого Ниагарского водопада в Северной Америке.","wiki_en":"Iguazu Falls"},{"name":"Водопад Анхель","emoji":"💧","meta":["Венесуэла","водопад","природный объект"],"description":"Самый высокий непрерывный водопад в мире, низвергающийся с плоской вершины столовой горы в венесуэльской сельве. Вода падает с такой высоты, что часть потока превращается в туман, не долетая до земли.","fact":"Водопад назван в честь американского лётчика Джимми Эйнджела, который одним из первых пролетел над ним и сообщил о нём миру.","wiki_en":"Angel Falls"},{"name":"Галапагосские острова","emoji":"🐢","meta":["Эквадор","вулканический архипелаг","природный объект"],"description":"Уединённый архипелаг в Тихом океане, чья уникальная фауна — гигантские черепахи, игуаны и вьюрки — натолкнула Чарльза Дарвина на мысли, впоследствии оформившиеся в теорию эволюции. Многие виды здесь не встречаются больше нигде на Земле.","fact":"Некоторые гигантские черепахи Галапагосских островов живут более ста лет и способны неделями обходиться без еды и воды.","wiki_en":"Galápagos Islands"},{"name":"Остров Пасхи","emoji":"🗿","meta":["Чили","остров с каменными статуями","примерно XIII–XVI века"],"description":"Крошечный остров в Тихом океане, знаменитый сотнями исполинских каменных статуй моаи, вырезанных древними полинезийскими жителями. Как именно многотонные фигуры перемещали по острову без современной техники, до конца не установлено.","fact":"У большинства статуй моаи непропорционально большие головы, а тела частично скрыты под землёй, из-за чего долгое время их считали безногими.","wiki_en":"Easter Island"},{"name":"Солончак Уюни","emoji":"🪞","meta":["Боливия","соляная пустыня","природный объект"],"description":"Крупнейшее в мире соляное плоскогорье, оставшееся на месте высохшего древнего озера в боливийских Андах. После дождей тонкий слой воды превращает поверхность в гигантское зеркало, в котором отражается небо.","fact":"Под ослепительно белой коркой соли Уюни скрываются огромные запасы лития, важного сырья для современных аккумуляторов.","wiki_en":"Salar de Uyuni"},{"name":"Сиднейский оперный театр","emoji":"⛵","meta":["Австралия","театр","1973"],"description":"Концертный и театральный комплекс на берегу Сиднейской гавани, чья крыша из белых изогнутых «парусов» стала главным символом Австралии. Необычная форма здания сделала его строительство долгим и куда более сложным, чем задумывалось изначально.","fact":"Автор проекта, датский архитектор Йорн Утзон, покинул Австралию из-за конфликтов ещё до завершения строительства и так и не увидел здание своими глазами.","wiki_en":"Sydney Opera House"},{"name":"Большой Барьерный риф","emoji":"🐠","meta":["Австралия","коралловый риф","природный объект"],"description":"Крупнейшая в мире система коралловых рифов, растянувшаяся вдоль северо-восточного побережья Австралии на тысячи километров. Она настолько велика, что её отдельные структуры можно разглядеть даже из космоса.","fact":"Из-за потепления океана и обесцвечивания кораллов значительная часть рифа находится под угрозой, что делает его символом хрупкости морских экосистем.","wiki_en":"Great Barrier Reef"},{"name":"Улуру","emoji":"🟠","meta":["Австралия","монолитная скала","природный объект"],"description":"Гигантская песчаниковая скала посреди австралийской пустыни, священная для местных аборигенов народа анангу. В зависимости от времени суток и погоды её поверхность меняет цвет от охристо-коричневого до ярко-красного.","fact":"Несмотря на прежнюю популярность подъёма на скалу у туристов, сегодня восхождение на Улуру полностью запрещено из уважения к традициям аборигенов.","wiki_en":"Uluru"},{"name":"Фудзияма","emoji":"🗻","meta":["Япония","вулкан","природный объект"],"description":"Симметричный конус спящего вулкана, самая высокая гора Японии и один из главных национальных символов страны. Её силуэт бесчисленное количество раз изображали на японских гравюрах и в живописи.","fact":"Гора Фудзи считается действующим, хоть и спящим вулканом — последнее известное извержение произошло ещё в начале XVIII века.","wiki_en":"Mount Fuji"},{"name":"Фусими Инари","emoji":"⛩️","meta":["Япония","синтоистское святилище","основано в VIII веке"],"description":"Святилище в Киото, посвящённое синтоистскому божеству риса Инари, знаменитое тысячами ярко-оранжевых тории, образующих туннели на склоне горы. Каждые ворота пожертвованы компаниями или частными лицами, надеющимися на удачу в делах.","fact":"Тропа через все тории и святилища на горе занимает несколько часов пешего подъёма и спуска.","wiki_en":"Fushimi Inari-taisha"},{"name":"Запретный город","emoji":"🐉","meta":["Китай","императорский дворцовый комплекс","XV век"],"description":"Огромный дворцовый комплекс в центре Пекина, столетиями служивший резиденцией китайских императоров и остававшийся закрытым для простых людей. Сегодня на его территории работает музей с богатейшей коллекцией императорских сокровищ.","fact":"По легенде, в Запретном городе 9999 помещений — на одно меньше десяти тысяч, которые приписывали дворцу небесного владыки.","wiki_en":"Forbidden City"},{"name":"Терракотовая армия","emoji":"🏺","meta":["Китай","погребальный комплекс","III век до н.э."],"description":"Тысячи глиняных воинов, лошадей и колесниц в натуральную величину, захороненные рядом с гробницей первого императора Китая Цинь Шихуанди для защиты его в загробной жизни. Каждая фигура имеет индивидуальные черты лица.","fact":"Армию обнаружили случайно в 1974 году местные крестьяне, копавшие колодец, — так на свет вышло одно из крупнейших археологических открытий XX века.","wiki_en":"Terracotta Army"},{"name":"Дворец Потала","emoji":"☸️","meta":["Китай","дворец-монастырь","XVII век"],"description":"Величественный дворец на скалистом холме в Лхасе, бывшая зимняя резиденция далай-лам и центр тибетского буддизма. Его белые и красные корпуса с тысячами комнат хранят статуи, реликвии и гробницы прежних правителей Тибета.","fact":"Дворец построен на высоте более трёх с половиной тысяч метров, что делает его одним из самых высокогорных монументальных сооружений мира.","wiki_en":"Potala Palace"},{"name":"Бухта Халонг","emoji":"🌊","meta":["Вьетнам","морская бухта с карстовыми островами","природный объект"],"description":"Бухта на севере Вьетнама, усеянная тысячами известняковых островов и скал причудливой формы, поднимающихся прямо из изумрудной воды. Туристов возят между островами на традиционных деревянных джонках.","fact":"Название бухты переводится как «место, где дракон спускается в море», согласно древней вьетнамской легенде о драконе, защищавшем страну.","wiki_en":"Ha Long Bay"},{"name":"Марина-Бэй Сэндс","emoji":"🏊","meta":["Сингапур","гостинично-развлекательный комплекс","2010"],"description":"Комплекс из трёх башен-отелей в Сингапуре, увенчанных гигантской платформой в форме лодки с бассейном на крыше. Отсюда открывается панорама на весь деловой центр города-государства.","fact":"Бассейн на крыше комплекса считается одним из самых больших и высоко расположенных бассейнов в мире, открытых для постояльцев отеля.","wiki_en":"Marina Bay Sands"},{"name":"Башни Петронас","emoji":"🔗","meta":["Малайзия","небоскрёбы-близнецы","1998"],"description":"Две одинаковые стальные башни в Куала-Лумпуре, долгое время остававшиеся самыми высокими зданиями мира, соединённые на середине высоты двухуровневым мостом-переходом. Их геометричный дизайн вдохновлён исламскими орнаментами.","fact":"Мост между башнями Петронас не закреплён жёстко с обеих сторон — это позволяет конструкции слегка смещаться при раскачивании зданий на ветру.","wiki_en":"Petronas Towers"},{"name":"Боробудур","emoji":"🪷","meta":["Индонезия","буддийский храм","IX век"],"description":"Крупнейший в мире буддийский храм на острове Ява, построенный в виде ступенчатой пирамиды, украшенной тысячами рельефов и статуй Будды. Паломники поднимаются по его террасам, символически проходя путь от земного мира к просветлению.","fact":"На верхних террасах храма установлены десятки колоколообразных ступ, внутри каждой из которых спрятана статуя Будды.","wiki_en":"Borobudur"},{"name":"Водопад Виктория","emoji":"🌈","meta":["Замбия и Зимбабве","водопад","природный объект"],"description":"Один из крупнейших водопадов мира на реке Замбези, где стена воды обрушивается в узкое ущелье с оглушительным рёвом. Местное название водопада переводится как «гремящий дым» — именно так выглядят столбы водяной пыли, поднимающиеся над ущельем.","fact":"Брызги водопада Виктория поднимаются на такую высоту, что их видно за несколько десятков километров в ясную погоду.","wiki_en":"Victoria Falls"},{"name":"Килиманджаро","emoji":"🏔️","meta":["Танзания","гора-вулкан","природный объект"],"description":"Самая высокая гора Африки — спящий вулкан, чья заснеженная вершина поднимается прямо над саванной. Подняться на неё способны даже неподготовленные туристы, поскольку технически сложного альпинистского снаряжения маршрут не требует.","fact":"Ледники на вершине Килиманджаро постепенно тают, и учёные опасаются, что в обозримом будущем снежная шапка горы может исчезнуть.","wiki_en":"Mount Kilimanjaro"},{"name":"Серенгети","emoji":"🦓","meta":["Танзания","национальный парк и саванна","природный объект"],"description":"Бескрайняя саванна в Восточной Африке, где ежегодно проходит одна из самых масштабных миграций животных на планете — миллионы антилоп гну и зебр движутся вслед за сезонными дождями. Здесь же обитают крупнейшие популяции львов и других хищников континента.","fact":"Название «Серенгети» происходит из языка масаи и означает примерно «бескрайняя равнина».","wiki_en":"Serengeti"},{"name":"Столовая гора","emoji":"🌫️","meta":["ЮАР","гора с плоской вершиной","природный объект"],"description":"Гора с почти идеально плоской вершиной, возвышающаяся над Кейптауном и видная практически из любой точки города. Когда облака стелются по её плоской верхушке, местные называют это явление «скатертью».","fact":"На вершину Столовой горы можно подняться пешком по нескольким маршрутам или за несколько минут доехать на канатной дороге с вращающейся кабиной.","wiki_en":"Table Mountain"},{"name":"Эверест","emoji":"🧗","meta":["Непал и Китай","гора","природный объект"],"description":"Самая высокая гора на Земле, расположенная в Гималаях на границе Непала и Тибета. Восхождение на её вершину десятилетиями остаётся одним из самых престижных и опасных испытаний для альпинистов со всего мира.","fact":"Первое подтверждённое восхождение на Эверест совершили Эдмунд Хиллари и Тенцинг Норгей в 1953 году.","wiki_en":"Mount Everest"},{"name":"Йосемити","emoji":"🏔️","meta":["США","национальный парк","с 1890 года"],"description":"Гранитные стены Эль-Капитан и Хаф-Доум возвышаются над калифорнийской долиной, а один из самых высоких водопадов Северной Америки шумит здесь с весны до лета. Секвойи, альпийские луга и ледниковые озёра делают Йосемити символом дикой природы США.","fact":"Скала Эль-Капитан в Йосемити — одна из крупнейших цельных гранитных глыб в мире и мечта скалолазов со всего света.","wiki_en":"Yosemite National Park"},{"name":"Зайон","emoji":"🏞️","meta":["США","национальный парк","с 1919 года"],"description":"Узкие красные каньоны реки Верджин прорезают песчаниковые скалы Юты, а тропа Angels Landing с цепями вдоль обрыва стала одним из самых известных маршрутов страны. Название парку дали мормонские поселенцы, увидевшие в этих скалах библейское святилище.","fact":"Узкий каньон Зайона местами сужается до нескольких метров в ширину при стенах высотой в сотни метров.","wiki_en":"Zion National Park"},{"name":"Брайс-Каньон","emoji":"🗿","meta":["США","национальный парк","с 1928 года"],"description":"Тысячи оранжево-красных скальных шпилей худу выстроились здесь амфитеатром, который особенно эффектно подсвечивается на рассвете. Формы скал возникли благодаря многовековому циклу замерзания и оттаивания воды в трещинах известняка.","fact":"В Брайс-Каньоне находится самое большое в мире скопление скальных образований худу.","wiki_en":"Bryce Canyon National Park"},{"name":"Арки (национальный парк)","emoji":"🌉","meta":["США","национальный парк","с 1971 года"],"description":"На сравнительно небольшой территории здесь насчитывается более двух тысяч природных каменных арок, включая знаменитую Дэликит-Арч. Красные песчаниковые формации возникли за миллионы лет под действием воды, ветра и перепадов температур.","fact":"Арка Дэликит-Арч, изображённая на номерных знаках Юты, — одна из самых узнаваемых природных арок в мире.","wiki_en":"Arches National Park"},{"name":"Долина Смерти","emoji":"🌡️","meta":["США","национальный парк","с 1994 года"],"description":"Одно из самых жарких и засушливых мест на планете, где летом столбик термометра регулярно превышает 50 градусов. Несмотря на суровый климат, весной после редких дождей пустыня ненадолго покрывается ковром цветущих растений.","fact":"В Долине Смерти в 1913 году зафиксирована одна из самых высоких температур воздуха, когда-либо официально измеренных на Земле.","wiki_en":"Death Valley National Park"},{"name":"Секвойя (национальный парк)","emoji":"🌲","meta":["США","национальный парк","с 1890 года"],"description":"Здесь растут гигантские секвойядендроны — одни из крупнейших живых организмов на планете, включая дерево генерала Шермана. Возраст некоторых деревьев в парке насчитывает более двух тысяч лет.","fact":"Дерево генерала Шермана в парке Секвойя считается крупнейшим по объёму древесины живым деревом на Земле.","wiki_en":"Sequoia National Park"},{"name":"Глейшер","emoji":"🧊","meta":["США","национальный парк","с 1910 года"],"description":"Горный парк на границе с Канадой назван в честь ледников, которые когда-то покрывали здесь почти всю территорию. Панорамная дорога «Путь к солнцу» пересекает парк через перевал и считается одной из самых живописных в США.","fact":"Из нескольких десятков ледников, давших парку название, к нашему времени сохранилась лишь небольшая часть.","wiki_en":"Glacier National Park (U.S.)"},{"name":"Эверглейдс","emoji":"🐊","meta":["США","национальный парк","с 1947 года"],"description":"Крупнейшая субтропическая болотная система США — медленно текущая «река травы», где аллигаторы соседствуют с редкими птицами и мангровыми зарослями. Это единственное место в мире, где одновременно обитают аллигаторы и крокодилы.","fact":"В Эверглейдсе живёт флоридская пума — один из самых редких хищников Северной Америки, которых в природе осталось лишь несколько сотен.","wiki_en":"Everglades National Park"},{"name":"Джошуа-Три","emoji":"🌵","meta":["США","национальный парк","с 1994 года"],"description":"Пустынный парк в Калифорнии получил имя от юкки коротколистной, чьи причудливые силуэты напомнили мормонским поселенцам библейского пророка с воздетыми руками. Здесь встречаются сразу две пустыни — Мохаве и Колорадо — со своими экосистемами.","fact":"Деревья Джошуа, давшие парку имя, на самом деле не деревья, а гигантские представители семейства спаржевых.","wiki_en":"Joshua Tree National Park"},{"name":"Кратерное озеро","emoji":"🌋","meta":["США","национальный парк","с 1902 года"],"description":"Самое глубокое озеро США заполняет кальдеру вулкана Мазама, обрушившегося тысячи лет назад. Вода в озере настолько чистая, что кажется насыщенно-синей, а пополняется она только за счёт дождя и снега.","fact":"По Кратерному озеру больше века плавает вертикально стоящий древесный ствол, который прозвали «Стариком озера».","wiki_en":"Crater Lake National Park"},{"name":"Гора Рейнир","emoji":"🗻","meta":["США","действующий вулкан","нацпарк с 1899 года"],"description":"Заснеженный стратовулкан возвышается над Сиэтлом и считается одним из самых опасных действующих вулканов США из-за близости крупных городов. Ледники на его склонах питают несколько рек региона.","fact":"Гора Рейнир — самая высокая вершина каскадной вулканической дуги и один из самых оледенелых пиков США вне Аляски.","wiki_en":"Mount Rainier"},{"name":"Антилопа-Каньон","emoji":"🌀","meta":["США","каньон с щелевидными стенами","популярен с 1990-х"],"description":"Извилистые оранжевые стены этого щелевидного каньона в Аризоне отшлифованы вековой эрозией песчаника и подсвечиваются лучами солнца, проникающими сверху. Место находится на землях народа навахо и посещается только с местным гидом.","fact":"Каньон формировался тысячи лет внезапными паводками, которые до сих пор представляют опасность для посетителей.","wiki_en":"Antelope Canyon"},{"name":"Подкова (излучина Колорадо)","emoji":"🌊","meta":["США","изгиб каньона реки Колорадо","популярен с 2010-х"],"description":"Река Колорадо здесь делает почти замкнутую петлю вокруг скалистого мыса, образуя вид, напоминающий подкову. Со смотровой площадки над обрывом открывается один из самых фотографируемых пейзажей американского Юго-Запада.","fact":"Излучина реки в форме подковы образовалась за миллионы лет, пока Колорадо прорезала слои песчаника плато.","wiki_en":"Horseshoe Bend (Arizona)"},{"name":"Уиллис-тауэр","emoji":"🏙️","meta":["США","небоскрёб","построен в 1973 году"],"description":"Десятилетиями это было самое высокое здание мира, пока его не обошли небоскрёбы Азии. На верхних этажах устроена смотровая площадка со стеклянными кабинками, выступающими за фасад здания.","fact":"Стеклянные балконы-кабинки Skydeck на верхних этажах Уиллис-тауэр позволяют посмотреть вниз сквозь прозрачный пол.","wiki_en":"Willis Tower"},{"name":"Космическая игла","emoji":"🛸","meta":["США","башня со смотровой площадкой","построена в 1962 году"],"description":"Башня с дискообразной вершиной построена в Сиэтле к Всемирной выставке и с тех пор стала символом города. На высоте нескольких десятков этажей расположены смотровая площадка и вращающийся ресторан.","fact":"После реконструкции на смотровой площадке Космической иглы появился вращающийся стеклянный пол, сквозь который видно город внизу.","wiki_en":"Space Needle"},{"name":"Мемориал Линкольна","emoji":"🏛️","meta":["США","мемориал","открыт в 1922 году"],"description":"Монументальное здание в неоклассическом стиле на Национальной аллее в Вашингтоне хранит гигантскую мраморную статую шестнадцатого президента США. Именно на его ступенях в 1963 году произносил свою знаменитую речь Мартин Лютер Кинг.","fact":"Сидящая фигура Линкольна внутри мемориала достигает примерно шести метров и сложена из множества мраморных блоков.","wiki_en":"Lincoln Memorial"},{"name":"Монумент Вашингтона","emoji":"🗼","meta":["США","обелиск","завершён в 1884 году"],"description":"Мраморный обелиск на Национальной аллее в Вашингтоне возведён в память первого президента США и после постройки несколько лет оставался самым высоким сооружением в мире, пока его не обошла Эйфелева башня. Строительство растянулось на десятилетия и было прервано нехваткой средств.","fact":"Из-за долгой паузы в строительстве нижняя и верхняя части обелиска сложены из мрамора немного разных оттенков.","wiki_en":"Washington Monument"},{"name":"Капитолий США","emoji":"🏛️","meta":["США","здание парламента","строительство началось в 1793 году"],"description":"Резиденция Конгресса США увенчана узнаваемым белым куполом и стоит на холме, который из-за неё и стал называться Капитолийским. Первый камень был заложен ещё в конце XVIII века, а нынешний купол достроили уже во время Гражданской войны.","fact":"Строительство купола Капитолия продолжалось даже во время Гражданской войны, как символ единства страны.","wiki_en":"United States Capitol"},{"name":"Гувер-дамба","emoji":"🌊","meta":["США","плотина","построена в 1930-х годах"],"description":"Одна из крупнейших бетонных плотин своего времени перегородила реку Колорадо на границе Невады и Аризоны, создав водохранилище Мид. Строительство стало символом инженерных возможностей США в разгар Великой депрессии.","fact":"На момент постройки Гувер-дамба была самой высокой плотиной в мире, а её турбины и сегодня снабжают электричеством несколько штатов.","wiki_en":"Hoover Dam"},{"name":"Смитсоновский институт","emoji":"🏛️","meta":["США","музейно-научный комплекс","основан в 1846 году"],"description":"Крупнейший в мире музейно-исследовательский комплекс объединяет десятки музеев и зоопарк в Вашингтоне, вход в большинство из которых бесплатный. Основан он был на средства британского учёного, который никогда не бывал в США.","fact":"В собраниях института хранятся десятки миллионов экспонатов — от самолёта братьев Райт до знаменитого алмаза «Хоуп».","wiki_en":"Smithsonian Institution"},{"name":"Пайк-плейс-маркет","emoji":"🐟","meta":["США","рынок","открыт в 1907 году"],"description":"Один из старейших постоянно действующих фермерских рынков США в Сиэтле знаменит продавцами рыбы, перебрасывающими лосося через прилавок на потеху публике. Здесь же, по соседству, открылась самая первая кофейня сети Starbucks.","fact":"Рынок появился в 1907 году, когда горожане потребовали покупать продукты напрямую у фермеров, минуя перекупщиков.","wiki_en":"Pike Place Market"},{"name":"Диснейуорлд","emoji":"🏰","meta":["США","парк развлечений","открыт в 1971 году"],"description":"Крупнейший по площади парк развлечений в мире раскинулся во Флориде и включает несколько тематических зон, отелей и полей для гольфа. Замок Золушки в его центре стал одним из самых узнаваемых силуэтов индустрии развлечений.","fact":"Территория Диснейуорлда во Флориде по площади сопоставима с небольшим городом и превышает размеры Манхэттена.","wiki_en":"Walt Disney World"},{"name":"Кратер Метеор","emoji":"☄️","meta":["США","метеоритный кратер","около 50 тыс. лет назад"],"description":"Один из наиболее хорошо сохранившихся метеоритных кратеров на Земле возник в пустыне Аризоны от удара небольшого металлического астероида. Его использовали для тренировок астронавты программы «Аполлон» перед полётами на Луну.","fact":"Долго считалось, что воронка возникла из-за вулканической активности, и её метеоритное происхождение признали лишь в XX веке.","wiki_en":"Meteor Crater"},{"name":"Форт Аламо","emoji":"🪖","meta":["США","миссия-крепость","основана в XVIII веке"],"description":"Бывшая католическая миссия в Сан-Антонио, Техас, стала местом знаменитой осады во время войны за независимость Техаса от Мексики. Фраза «Помни Аламо!» до сих пор остаётся в американской культуре символом стойкости перед лицом поражения.","fact":"Почти все защитники Аламо погибли во время осады 1836 года, но их сопротивление стало символом для дальнейшей борьбы техасцев.","wiki_en":"Alamo Mission in San Antonio"},{"name":"Гора Денали","emoji":"🏔️","meta":["США","высочайшая гора Северной Америки","нацпарк с 1917 года"],"description":"Заснеженная вершина на Аляске — самая высокая точка Северной Америки, притягивающая альпинистов со всего мира суровыми условиями восхождения. Название «Денали» на языке коренных атабасков означает «высокая».","fact":"Перепад высот от подножия до вершины у Денали один из самых больших в мире — больше, чем у Эвереста, который стоит на высоком плато.","wiki_en":"Denali"},{"name":"Исаакиевский собор","emoji":"⛪","meta":["Россия","собор","построен в середине XIX века"],"description":"Один из крупнейших купольных соборов мира строился в Петербурге почти четыре десятилетия и стал архитектурной визитной карточкой города. С колоннады под куполом открывается панорамный вид на исторический центр.","fact":"Монолитные гранитные колонны портиков весят около ста тонн каждая, и установили их ещё до того, как возвели стены собора.","wiki_en":"Saint Isaac's Cathedral"},{"name":"Казанский собор","emoji":"⛪","meta":["Россия","собор","построен в начале XIX века"],"description":"Собор на Невском проспекте в Петербурге построен по образцу собора Святого Петра в Риме и увенчан полукруглой колоннадой. После Отечественной войны 1812 года здесь похоронен фельдмаршал Михаил Кутузов.","fact":"Собор назван в честь Казанской иконы Божией Матери, чей почитаемый список хранился здесь как главная святыня.","wiki_en":"Kazan Cathedral, Saint Petersburg"},{"name":"Храм Христа Спасителя","emoji":"⛪","meta":["Россия","собор","воссоздан в 1990-х годах"],"description":"Крупнейший православный храм России в Москве был взорван в советское время и восстановлен заново уже в конце XX века по образцу утраченного оригинала. Изначально собор строился в память о победе в Отечественной войне 1812 года.","fact":"На месте разрушенного храма несколько десятилетий работал открытый бассейн «Москва», действовавший даже зимой.","wiki_en":"Cathedral of Christ the Saviour"},{"name":"Новодевичий монастырь","emoji":"⛪","meta":["Россия","монастырь","основан в XVI веке"],"description":"Один из самых известных женских монастырей Москвы основан в честь возвращения Смоленска в состав русских земель. На территории монастыря находится некрополь, где похоронены многие видные деятели русской культуры и истории.","fact":"Архитектурный ансамбль Новодевичьего монастыря включён в список Всемирного наследия ЮНЕСКО.","wiki_en":"Novodevichy Convent"},{"name":"Третьяковская галерея","emoji":"🖼️","meta":["Россия","художественный музей","основана в 1856 году"],"description":"Крупнейшее собрание русского изобразительного искусства выросло из частной коллекции московского купца и мецената Павла Третьякова. Сегодня галерея хранит работы от древнерусских икон до полотен передвижников и авангарда.","fact":"Коллекция Третьяковской галереи началась с личного собрания картин купца Павла Третьякова, подарившего его городу Москве.","wiki_en":"Tretyakov Gallery"},{"name":"Русский музей","emoji":"🎨","meta":["Россия","художественный музей","основан в 1895 году"],"description":"Первый в стране государственный музей русского изобразительного искусства расположен в Петербурге, в Михайловском дворце. Его коллекция охватывает почти всю историю русской живописи и скульптуры, от икон до авангарда XX века.","fact":"Русский музей был основан по указу императора Николая II и стал первым в России государственным музеем национального искусства.","wiki_en":"Russian Museum"},{"name":"ВДНХ","emoji":"🎡","meta":["Россия","выставочный комплекс","открыт в 1939 году"],"description":"Гигантский выставочный комплекс в Москве изначально создавался для демонстрации достижений советского сельского хозяйства и промышленности. Сегодня его павильоны в стиле сталинского ампира соседствуют с фонтанами, музеями и парковыми зонами.","fact":"Фонтан «Дружба народов» на ВДНХ украшен золочёными скульптурами, символизирующими союзные республики СССР.","wiki_en":"Exhibition of Achievements of National Economy","wiki_ru":"Выставка достижений народного хозяйства"},{"name":"Останкинская телебашня","emoji":"📡","meta":["Россия","телебашня","построена в 1967 году"],"description":"Одна из самых высоких телебашен мира возвышается над Москвой и десятилетиями обеспечивала телевещание на весь регион. На высоте нескольких сотен метров работает смотровая площадка с видом на город.","fact":"После постройки Останкинская телебашня несколько лет была самым высоким свободно стоящим сооружением в мире.","wiki_en":"Ostankino Tower"},{"name":"Царь-пушка","emoji":"⚔️","meta":["Россия","артиллерийское орудие-памятник","отлита в 1586 году"],"description":"Гигантское бронзовое орудие установлено на территории Московского Кремля и считается одним из крупнейших по калибру артиллерийских стволов в истории. Историки спорят, стреляла ли пушка хоть раз за свою историю.","fact":"Несмотря на внушительные размеры, нет достоверных свидетельств того, что Царь-пушка когда-либо использовалась в бою.","wiki_en":"Tsar Cannon"},{"name":"Царь-колокол","emoji":"🔔","meta":["Россия","колокол-памятник","отлит в 1735 году"],"description":"Крупнейший в мире колокол так никогда и не был поднят на звонницу — во время пожара от него откололся массивный кусок. Сегодня он стоит на постаменте в Московском Кремле как памятник литейному искусству XVIII века.","fact":"От Царь-колокола откололся кусок весом в несколько тонн ещё до того, как колокол успели поднять и использовать по назначению.","wiki_en":"Tsar Bell"},{"name":"Мамаев курган","emoji":"🕊️","meta":["Россия","мемориальный комплекс","открыт в 1967 году"],"description":"Курган в Волгограде, где во время Сталинградской битвы шли одни из самых ожесточённых боёв Второй мировой войны, стал местом одного из крупнейших военных мемориалов мира. Его венчает статуя «Родина-мать зовёт!».","fact":"На момент открытия статуя «Родина-мать зовёт!» была самой высокой скульптурой в мире.","wiki_en":"Mamayev Kurgan"},{"name":"Куршская коса","emoji":"🏖️","meta":["Россия","песчаная коса","нацпарк с 1987 года"],"description":"Узкая песчаная полоса между Балтийским морем и Куршским заливом протянулась почти на сотню километров и делится между Россией и Литвой. Здесь встречаются гигантские дюны и «танцующий лес» с необычно изогнутыми стволами сосен.","fact":"В «танцующем лесу» на Куршской косе стволы сосен закручены и изогнуты по неясной до конца причине.","wiki_en":"Curonian Spit"},{"name":"Долина гейзеров","emoji":"♨️","meta":["Россия","гейзерное поле","открыта в 1941 году"],"description":"Одно из немногих крупных скоплений гейзеров в мире находится на Камчатке в труднодоступном каньоне реки Гейзерной. Десятки горячих источников и фонтанов пара делают это место уникальным геотермальным феноменом.","fact":"Долину гейзеров на Камчатке открыла в 1941 году исследовательница Татьяна Устинова, случайно наткнувшаяся на неё во время экспедиции.","wiki_en":"Valley of Geysers"},{"name":"Ленские столбы","emoji":"🪨","meta":["Россия","скальные останцы","нацпарк с 1995 года"],"description":"Вертикальные известняковые скалы высотой в десятки метров тянутся на многие километры вдоль реки Лена в Якутии. В отложениях этих мест находят кости мамонтов и других животных ледникового периода.","fact":"В окрестностях Ленских столбов регулярно находят хорошо сохранившиеся останки мамонтов и других ископаемых животных.","wiki_en":"Lena Pillars"},{"name":"Плато Путорана","emoji":"⛰️","meta":["Россия","базальтовое плато","заповедник с 1988 года"],"description":"Труднодоступное плато на севере Сибири изрезано глубокими каньонами и сотнями водопадов, а его базальтовые ступени напоминают террасы. Из-за удалённости территория остаётся одной из наименее посещаемых в России.","fact":"На плато Путорана находится один из самых высоких водопадов России, спрятанный в труднодоступном каньоне.","wiki_en":"Putorana Plateau"},{"name":"Соловецкие острова","emoji":"🏝️","meta":["Россия","архипелаг с монастырём","монастырь с XV века"],"description":"Архипелаг в Белом море известен древним монастырём, который в разные эпохи был и духовным центром, и местом заключения. Суровый климат и удалённость веками формировали особый уклад жизни здешних насельников.","fact":"В советское время на территории Соловецкого монастыря располагался один из первых лагерей особого назначения.","wiki_en":"Solovetsky Islands"},{"name":"Золотое кольцо России","emoji":"💍","meta":["Россия","туристический маршрут","сложился в 1960-х годах"],"description":"Название объединяет несколько древних городов вокруг Москвы — Суздаль, Владимир, Сергиев Посад и другие, — сохранивших белокаменные храмы и кремли домонгольских времён. Маршрут сформировался как туристический бренд в советские годы.","fact":"Термин «Золотое кольцо» придумал в 1960-х годах журналист Юрий Бычков, объединивший старинные города в единый туристический маршрут.","wiki_en":"Golden Ring of Russia","wiki_ru":"Золотое кольцо России"},{"name":"Дворцовая площадь","emoji":"🏛️","meta":["Россия","площадь","сложилась в XVIII–XIX веках"],"description":"Главная площадь Петербурга окружена Зимним дворцом и зданием Главного штаба с триумфальной аркой, а в центре возвышается Александровская колонна. Здесь проходили ключевые события российской истории, включая события 1917 года.","fact":"Александровская колонна в центре Дворцовой площади удерживается на постаменте исключительно собственным весом, без креплений.","wiki_en":"Palace Square"},{"name":"Дворцовый мост","emoji":"🌉","meta":["Россия","разводной мост","построен в 1916 году"],"description":"Один из самых узнаваемых разводных мостов Петербурга соединяет Дворцовую набережную с Васильевским островом через Неву. Развод его крыльев по ночам в период навигации стал одним из символов города и туристическим ритуалом.","fact":"Постоянный мост на этом месте появился лишь в начале XX века — до того берега Невы связывал наплавной мост на баржах.","wiki_en":"Palace Bridge"},{"name":"Валаам","emoji":"🏝️","meta":["Россия","остров с монастырём","предположительно XIV век"],"description":"Архипелаг на Ладожском озере известен суровой северной природой и одним из старейших монастырей русского Севера. Скалистые берега, сосновые леса и уединённые скиты веками привлекали сюда паломников и художников.","fact":"Пейзажи Валаама вдохновляли многих русских художников, включая Ивана Шишкина, побывавшего здесь в молодости.","wiki_en":"Valaam"},{"name":"Кунгурская ледяная пещера","emoji":"🧊","meta":["Россия","карстовая пещера","открыта для посещения в 1914 году"],"description":"Одна из крупнейших карстовых пещер России на Урале славится ледяными гротами, подземными озёрами и причудливыми кристаллами инея. Часть её ходов украшена искусственной подсветкой, превращающей лёд в разноцветные узоры.","fact":"В некоторых гротах Кунгурской пещеры лёд сохраняется круглый год даже в разгар уральского лета.","wiki_en":"Kungur Ice Cave"},{"name":"Красноярские столбы","emoji":"⛰️","meta":["Россия","скальные останцы","заповедник с 1925 года"],"description":"Причудливые сиенитовые скалы в тайге под Красноярском издавна привлекали скалолазов, включая местных «столбистов», лазающих без страховки. Заповедник создан для сохранения уникального ландшафта и окружающей его тайги.","fact":"Заповедник на Столбах — один из старейших в России: скалы находятся под охраной уже около ста лет.","wiki_en":"Stolby Nature Reserve"},{"name":"Остров Ольхон","emoji":"🏝️","meta":["Россия","крупнейший остров Байкала","часть нацпарка с 1986 года"],"description":"Самый большой остров на Байкале считается духовным центром бурятского шаманизма и местом с одной из самых высоких концентраций солнечных дней в России. Скала Шаманка на его берегу — один из самых почитаемых природных символов региона.","fact":"Скала Шаманка на Ольхоне считается одним из девяти священных мест Азии в традициях местного шаманизма.","wiki_en":"Olkhon"},{"name":"Домбай","emoji":"🎿","meta":["Россия","горнолыжный курорт","туристический центр с 1920-х"],"description":"Горный посёлок на Кавказе, окружённый ледниками и вершинами высотой более четырёх тысяч метров, стал одним из первых советских центров альпинизма и горных лыж. Канатные дороги поднимают туристов к площадкам с видом на Эльбрус и Главный Кавказский хребет.","fact":"С видовых точек над Домбаем в ясную погоду можно разглядеть Эльбрус — высочайшую вершину Европы.","wiki_en":"Dombai","wiki_ru":"Домбай (курортный посёлок)"},{"name":"Суздальский кремль","emoji":"🏰","meta":["Россия","кремль","основан в XI веке"],"description":"Древнейшая часть города Суздаля сохранила земляные валы и собор с редкими для домонгольской архитектуры золотыми вратами. Небольшие размеры и отсутствие крупной современной застройки сделали Суздаль своеобразным музеем под открытым небом.","fact":"Суздальский кремль — один из немногих в России, где почти не сохранилось поздних построек, заслоняющих древний облик города.","wiki_en":"Suzdal Kremlin"},{"name":"Лондонский Тауэр","emoji":"🏰","meta":["Великобритания","крепость-музей","построен в XI веке"],"description":"Крепость на Темзе заложена Вильгельмом Завоевателем и за свою историю успела побывать королевской резиденцией, тюрьмой и хранилищем королевских драгоценностей. Чёрные вороны, живущие на территории Тауэра, по легенде охраняют британскую монархию.","fact":"По легенде, если вороны когда-нибудь покинут Тауэр, британская монархия падёт, поэтому им подрезают крылья.","wiki_en":"Tower of London"},{"name":"Вестминстерское аббатство","emoji":"⛪","meta":["Великобритания","аббатство","готический облик с XIII века"],"description":"Готическое аббатство в Лондоне веками служит местом коронации и захоронения британских монархов, а также многих выдающихся деятелей науки и искусства. Здесь же в 2011 году венчались принц Уильям и Кейт Миддлтон.","fact":"В Вестминстерском аббатстве похоронены Исаак Ньютон, Чарльз Дарвин и десятки британских монархов.","wiki_en":"Westminster Abbey"},{"name":"Лондонский глаз","emoji":"🎡","meta":["Великобритания","колесо обозрения","открыто в 2000 году"],"description":"Гигантское колесо обозрения на южном берегу Темзы возвели как временный аттракцион к встрече нового тысячелетия, но оно осталось одной из главных достопримечательностей Лондона. Полный оборот кабинки занимает около получаса.","fact":"Колесо вращается непрерывно и так медленно, что пассажиры успевают заходить в кабинки на ходу, без остановки.","wiki_en":"London Eye"},{"name":"Собор Святого Павла","emoji":"⛪","meta":["Великобритания","собор","построен в 1675–1710 годах"],"description":"Купольный собор в Лондоне возведён по проекту архитектора Кристофера Рена после Великого лондонского пожара, уничтожившего прежнее здание. Его купол долгое время оставался одним из самых высоких сооружений города.","fact":"Собор Святого Павла пережил бомбардировки Лондона во время Второй мировой войны почти невредимым, что стало символом стойкости города.","wiki_en":"St Paul's Cathedral"},{"name":"Плитвицкие озёра","emoji":"🏞️","meta":["Хорватия","система озёр и водопадов","нацпарк с 1949 года"],"description":"Шестнадцать бирюзовых озёр соединены между собой каскадами водопадов и деревянными настилами, по которым проложены пешеходные маршруты. Цвет воды меняется в зависимости от минерального состава и количества водорослей.","fact":"Озёра разделены природными травертиновыми барьерами, которые нарастают сами и постепенно меняют рисунок каскадов.","wiki_en":"Plitvice Lakes National Park"},{"name":"Озеро Комо","emoji":"🛥️","meta":["Италия","озеро","ледникового происхождения"],"description":"Одно из самых глубоких озёр Европы у подножия Альп давно облюбовали европейская аристократия и знаменитости за виллы на живописных берегах. Форма озера напоминает перевёрнутую букву Y, что делает его особенно узнаваемым.","fact":"Виллы на берегах Комо не раз становились декорациями большого кино — от «Звёздных войн» до фильмов о Джеймсе Бонде.","wiki_en":"Lake Como"},{"name":"Красное море","emoji":"🐠","meta":["между Африкой и Азией","море","формируется около 30 млн лет"],"description":"Один из самых популярных в мире регионов для дайвинга благодаря тёплой воде, прозрачности и богатым коралловым рифам. Море образовалось в результате раскола африканской и аравийской литосферных плит.","fact":"Название «Красное море» может быть связано с сезонным цветением водорослей, придающих воде красноватый оттенок.","wiki_en":"Red Sea"},{"name":"Северное сияние","emoji":"🌌","meta":["полярные регионы","природное световое явление","наблюдается с древности"],"description":"Свечение неба возникает, когда заряженные частицы солнечного ветра сталкиваются с атмосферой Земли вблизи полюсов. Цвет зависит от того, с какими газами атмосферы происходит столкновение — чаще всего это зелёные и розоватые оттенки.","fact":"Зелёный цвет северного сияния возникает из-за свечения атомов кислорода на определённой высоте в атмосфере.","wiki_en":"Aurora"},{"name":"Линии Наска","emoji":"📐","meta":["Перу","геоглифы","созданы около 2000 лет назад"],"description":"Гигантские изображения животных и геометрических фигур, выцарапанные на плато в пустыне Перу, различимы целиком только с высоты птичьего полёта. Их назначение до сих пор остаётся предметом споров среди учёных.","fact":"Целиком эти рисунки разглядели лишь в XX веке, когда над плато начали летать самолёты.","wiki_en":"Nazca Lines"},{"name":"Озеро Титикака","emoji":"🛶","meta":["Перу и Боливия","высокогорное озеро","одно из древнейших озёр"],"description":"Одно из самых высокогорных судоходных озёр в мире лежит на границе Перу и Боливии среди Анд. На его плавучих островах, сплетённых из тростника, до сих пор живут представители народа уру.","fact":"По объёму воды Титикака — крупнейшее озеро Южной Америки, а его берега лежат на высоте около четырёх километров.","wiki_en":"Lake Titicaca"},{"name":"Патагония","emoji":"🏔️","meta":["Аргентина и Чили","природный регион","формировалась миллионы лет"],"description":"Обширный малонаселённый регион на юге Южной Америки известен ледниками, острыми гранитными пиками вроде Фицрой и суровыми ветрами степей. Национальные парки региона привлекают альпинистов и любителей треккинга со всего мира.","fact":"Ледник Перито-Морено в аргентинской Патагонии — один из немногих в мире ледников, которые не отступают, а местами даже нарастают.","wiki_en":"Patagonia"},{"name":"Золотой храм в Амритсаре","emoji":"🛕","meta":["Индия","главный сикхский храм","построен в конце XVI века"],"description":"Главная святыня сикхизма стоит посреди искусственного озера и облицована сусальным золотом, из-за чего и получила своё название. При храме бесплатно кормят десятки тысяч паломников и посетителей любой веры каждый день.","fact":"У храма четыре входа с разных сторон — как знак того, что он открыт для людей любого происхождения и веры.","wiki_en":"Golden Temple"},{"name":"Река Ганг","emoji":"🕉️","meta":["Индия","священная река","одна из древнейших почитаемых рек"],"description":"Река, берущая начало в Гималаях, считается священной в индуизме, и миллионы паломников ежегодно совершают в её водах ритуальные омовения. Вдоль её берегов расположены древние города, включая Варанаси, один из старейших постоянно населённых городов мира.","fact":"Вместе с Брахмапутрой Ганг образует крупнейшую в мире речную дельту, поросшую мангровыми лесами Сундарбана.","wiki_en":"Ganges"},{"name":"Гималаи","emoji":"🏔️","meta":["Азия","горная система","формируются около 50 млн лет"],"description":"Крупнейшая горная система планеты возникла в результате столкновения индийской и евразийской литосферных плит и продолжает расти. Здесь находится большинство восьмитысячников Земли, включая Эверест.","fact":"Все четырнадцать вершин мира высотой более восьми тысяч метров расположены в Гималаях и соседнем Каракоруме.","wiki_en":"Himalayas"},{"name":"Пустыня Сахара","emoji":"🏜️","meta":["Северная Африка","крупнейшая жаркая пустыня","пустыней стала тысячи лет назад"],"description":"Крупнейшая в мире жаркая пустыня простирается через территорию более десятка африканских стран, хотя тысячи лет назад на её месте была саванна с реками и озёрами. Сегодня здесь встречаются как бескрайние песчаные дюны, так и каменистые плато.","fact":"Днём в Сахаре бывает жарче 45 градусов, а ночью температура в пустыне способна упасть почти до нуля.","wiki_en":"Sahara"},{"name":"Замок Химэдзи","emoji":"🏯","meta":["Япония","замок","перестроен в начале XVII века"],"description":"Белоснежный замковый комплекс называют «замком белой цапли» за изящные изогнутые крыши, напоминающие крылья птицы. Это один из немногих японских замков, сохранивших подлинные деревянные постройки, а не современный бетонный новодел.","fact":"Замок Химэдзи — один из немногих японских замков, ни разу не разрушавшихся войной или пожаром за свою историю.","wiki_en":"Himeji Castle"},{"name":"Роща Арасияма","emoji":"🎋","meta":["Япония","бамбуковая роща","популярна с периода Хэйан"],"description":"Плотные заросли высокого бамбука в пригороде Киото создают тенистый зелёный коридор, где стебли раскачиваются и шумят на ветру над головой посетителей. Место издавна вдохновляло японских поэтов и художников.","fact":"Стволы бамбука в роще Арасияма могут вырастать на десятки сантиметров всего за одни сутки.","wiki_en":"Arashiyama"},{"name":"Токийская телебашня","emoji":"🗼","meta":["Япония","телебашня","построена в 1958 году"],"description":"Красно-белая башня в Токио создавалась по образцу Эйфелевой, но получилась выше своего французского прототипа. Долгое время она служила главной телевизионной вышкой города, а сегодня остаётся популярной смотровой площадкой и символом послевоенного восстановления Японии.","fact":"Полосатую окраску башни, в которой используется оранжевый оттенок, обновляют вручную примерно раз в пять лет.","wiki_en":"Tokyo Tower"},{"name":"Перекрёсток Сибуя","emoji":"🚦","meta":["Япония","городской перекрёсток","известен с середины XX века"],"description":"Один из самых оживлённых пешеходных перекрёстков мира в Токио одновременно пропускает в разных направлениях сотни людей, когда загорается зелёный свет во всех направлениях сразу. Окружающие небоскрёбы с рекламными экранами усиливают ощущение футуристического мегаполиса.","fact":"На перекрёстке Сибуя в пиковые моменты одновременно может переходить дорогу до нескольких тысяч человек.","wiki_en":"Shibuya Crossing"},{"name":"Горы Гуйлиня","emoji":"⛰️","meta":["Китай","карстовые горы","формировались миллионы лет"],"description":"Причудливые островерхие холмы вдоль реки Лицзян сложены из известняка и веками вдохновляли китайских художников и поэтов. Пейзажи этого региона считаются классическим воплощением традиционной китайской живописи.","fact":"Пейзаж Гуйлиня изображён на банкноте китайского юаня достоинством в 20 юаней.","wiki_en":"Guilin"},{"name":"Ворота Индии","emoji":"🏛️","meta":["Индия","триумфальная арка","построена в 1924 году"],"description":"Монументальная арка в Мумбаи возведена в память о визите британского короля Георга V и стала символом города на берегу Аравийского моря. Позже через эти же ворота уходили последние британские войска после провозглашения независимости Индии.","fact":"Арка сложена из жёлтого базальта и бетона, а в её облике смешаны индийские и европейские архитектурные мотивы.","wiki_en":"Gateway of India"},{"name":"Красный форт","emoji":"🏰","meta":["Индия","крепость","построена в середине XVII века"],"description":"Массивная крепость из красного песчаника в Дели служила главной резиденцией императоров династии Великих Моголов. Именно отсюда премьер-министр страны ежегодно обращается к нации в День независимости.","fact":"Имя форт получил за стены из красного песчаника, которые тянутся вокруг него больше двух километров.","wiki_en":"Red Fort"},{"name":"Эфес","emoji":"🏛️","meta":["Турция","древний город","основан в I тыс. до н. э."],"description":"Руины одного из крупнейших городов античного мира сохранили величественный фасад библиотеки Цельса и огромный античный театр. Некогда портовый город со временем оказался далеко от моря из-за постепенного заиления бухты.","fact":"Библиотека Цельса в Эфесе когда-то хранила тысячи свитков и считалась одной из крупнейших библиотек древнего мира.","wiki_en":"Ephesus"},{"name":"Долина Царей","emoji":"🪦","meta":["Египет","некрополь фараонов","использовался в XVI–XI вв. до н. э."],"description":"Скалистое ущелье на западном берегу Нила служило местом захоронения фараонов Нового царства, включая знаменитую гробницу Тутанхамона. Большинство гробниц были разграблены ещё в древности, но роспись на их стенах сохранилась до наших дней.","fact":"Гробница Тутанхамона в Долине Царей была найдена почти нетронутой грабителями — редчайший случай для египетской археологии.","wiki_en":"Valley of the Kings"},{"name":"Санторини","emoji":"🌅","meta":["Греция","вулканический остров","вид сложился после извержения"],"description":"Серповидный остров в Эгейском море возник после катастрофического извержения вулкана в бронзовом веке, изменившего очертания суши. Белоснежные домики на краю кальдеры и закаты над морем сделали остров одним из символов Греции.","fact":"Мощное извержение вулкана на Санторини в бронзовом веке, вероятно, повлияло на упадок минойской цивилизации на соседнем Крите.","wiki_en":"Santorini"},{"name":"Метеоры","emoji":"⛰️","meta":["Греция","скальные монастыри","монастыри основаны в XIV веке"],"description":"Православные монастыри построены на вершинах отвесных скальных столбов в центральной Греции, куда монахи веками поднимались по верёвочным лестницам. Название переводится как «парящие в воздухе» — именно такое впечатление производят обители издалека.","fact":"Долгое время попасть в монастыри Метеор можно было лишь в сетке на верёвке или по убираемым приставным лестницам.","wiki_en":"Meteora"},{"name":"Амазонка","emoji":"🐍","meta":["Южная Америка","река","формировалась миллионы лет"],"description":"Одна из крупнейших рек мира по объёму переносимой воды протекает через самый большой тропический лес планеты, который носит её имя. В бассейне реки обитает огромная доля всех известных видов животных и растений Земли.","fact":"Амазонка несёт в океан больше воды, чем следующие несколько по полноводности рек мира вместе взятые.","wiki_en":"Amazon River"},{"name":"Озеро Гарда","emoji":"🛥️","meta":["Италия","озеро","ледникового происхождения"],"description":"Крупнейшее озеро Италии у подножия Альп известно мягким климатом, оливковыми рощами и виноградниками на берегах. Небольшие города вокруг озера, такие как Сирмионе, сохранили средневековые замки и римские руины.","fact":"На полуострове Сирмионе на озере Гарда сохранились руины античной виллы, которую традиционно связывают с именем поэта Катулла.","wiki_en":"Lake Garda"},{"name":"Босфорский мост","emoji":"🌉","meta":["Турция","висячий мост","построен в 1973 году"],"description":"Первый постоянный мост через пролив Босфор соединил европейскую и азиатскую части Стамбула и символически объединил два континента. С открытием моста впервые стало возможно пересечь пролив на автомобиле, а не только на пароме.","fact":"Движение по мосту открыли в 1973 году, к пятидесятилетию Турецкой Республики.","wiki_en":"Bosphorus Bridge"},{"name":"Голубая лагуна","emoji":"♨️","meta":["Исландия","геотермальный курорт","открыт в 1992 году"],"description":"Бассейн с молочно-голубой минерализованной водой образовался как побочный продукт работы соседней геотермальной электростанции. Тёплая вода, богатая кремнезёмом и солями, круглый год привлекает посетителей даже в разгар исландской зимы.","fact":"Температура воды в лагуне круглый год держится около 38 градусов, независимо от погоды снаружи.","wiki_en":"Blue Lagoon (geothermal spa)"},{"name":"Пальма Джумейра","emoji":"🌴","meta":["ОАЭ","искусственный остров","построен в 2000-х годах"],"description":"Архипелаг в форме пальмы намыт в море у берегов Дубая и виден даже из космоса благодаря характерным очертаниям. На стволе и «листьях» острова расположены виллы, отели и жилые комплексы.","fact":"Остров намыли из миллионов кубометров песка со дна залива, а от волн его прикрывает внешний полумесяц-волнолом.","wiki_en":"Palm Jumeirah"},{"name":"Диснейленд","emoji":"🎢","meta":["США","парк развлечений","открыт в 1955 году"],"description":"Первый парк компании Disney открылся в Калифорнии по личной задумке Уолта Диснея и стал прообразом для десятков подобных парков по всему миру. Замок Спящей красавицы в его центре — один из самых узнаваемых силуэтов индустрии развлечений.","fact":"У входа в парк висит табличка, обещающая гостям оставить сегодняшний день позади и попасть в мир прошлого, будущего и фантазии.","wiki_en":"Disneyland"},{"name":"Оксфордский университет","emoji":"🎓","meta":["Великобритания","университет","преподавание с XI века"],"description":"Старейший университет англоязычного мира состоит из десятков самостоятельных колледжей, разбросанных по историческому центру города. Среди его выпускников — множество британских премьер-министров и нобелевских лауреатов.","fact":"Оксфорд старше державы ацтеков: занятия здесь шли ещё до того, как был основан Теночтитлан.","wiki_en":"University of Oxford"},{"name":"Кембриджский университет","emoji":"📚","meta":["Великобритания","университет","основан в 1209 году"],"description":"Университет возник после того, как часть учёных покинула Оксфорд после конфликта с местными жителями, и со временем стал его главным соперником. Колледжи вдоль реки Кем с зелёными лужайками и традицией катания на плоскодонках формируют неповторимый облик города.","fact":"В Кембридже учились Исаак Ньютон и Чарльз Дарвин, а всего с университетом связаны десятки нобелевских лауреатов.","wiki_en":"University of Cambridge"},{"name":"Музеи Ватикана","emoji":"🖼️","meta":["Ватикан","музейный комплекс","основаны в начале XVI века"],"description":"Один из крупнейших музейных комплексов мира собрал коллекции пап на протяжении столетий — от античных скульптур до полотен эпохи Возрождения. Путь по галереям традиционно завершается в Сикстинской капелле с росписями Микеланджело.","fact":"Галереи музеев тянутся на несколько километров, и обойти все залы за одно посещение практически невозможно.","wiki_en":"Vatican Museums"},{"name":"Сикстинская капелла","emoji":"🎨","meta":["Ватикан","капелла","построена в конце XV века"],"description":"Домовая капелла пап знаменита потолочной росписью Микеланджело с изображением сотворения мира и фреской «Страшный суд» на алтарной стене. Здесь же проходит конклав, на котором кардиналы избирают нового папу римского.","fact":"Вопреки распространённому мифу, Микеланджело расписывал потолок не лёжа на спине, а стоя на лесах с задранной вверх головой.","wiki_en":"Sistine Chapel"},{"name":"Галерея Уффици","emoji":"🖼️","meta":["Италия","художественный музей","открыта для публики в 1765 году"],"description":"Один из старейших художественных музеев Европы во Флоренции хранит одно из богатейших собраний живописи итальянского Возрождения, включая работы Боттичелли и Леонардо да Винчи. Здание изначально строилось как административные офисы правителей Тосканы.","fact":"Именно в Уффици хранится «Рождение Венеры» Боттичелли — одна из самых узнаваемых картин Возрождения.","wiki_en":"Uffizi"},{"name":"Мост Риальто","emoji":"🌉","meta":["Италия","мост","построен в конце XVI века"],"description":"Старейший из мостов через Гранд-канал в Венеции долгое время оставался единственным способом перейти канал пешком. Каменную арку моста с рядами лавочек по бокам спроектировали после того, как несколько прежних деревянных мостов обрушились.","fact":"Каменный мост возвели по проекту архитектора Антонио да Понте, чья фамилия дословно означает «с моста».","wiki_en":"Rialto Bridge"},{"name":"Гранд-канал","emoji":"🚤","meta":["Италия","главный канал Венеции","сложился как артерия в Средние века"],"description":"Главная водная артерия Венеции изгибается через весь город в форме перевёрнутой латинской буквы S, а вдоль его берегов стоят роскошные дворцы разных эпох. Вместо автомобилей по каналу передвигаются катера, вапоретто и гондолы.","fact":"Через весь Гранд-канал перекинуто всего четыре моста, поэтому венецианцы часто перебираются на другой берег на лодках-трагетто.","wiki_en":"Grand Canal (Venice)"},{"name":"Афинский Акрополь","emoji":"🏛️","meta":["Греция","комплекс древних храмов","Парфенон — V век до н. э."],"description":"Скалистый холм в центре Афин увенчан Парфеноном — храмом в честь богини Афины, который считается вершиной классической греческой архитектуры. Комплекс пережил войны, взрывы и века эрозии, но остаётся символом античной цивилизации.","fact":"Часть скульптур фриза Парфенона, известных как мраморы Элгина, хранится в Британском музее в Лондоне, а не в Афинах.","wiki_en":"Acropolis of Athens"},{"name":"Дельфы","emoji":"🏛️","meta":["Греция","древнее святилище","действовало с VIII века до н. э."],"description":"Святилище на склоне горы Парнас считалось у древних греков «пупом земли» и было домом знаменитого дельфийского оракула. Правители и полководцы со всей Греции приезжали сюда за предсказаниями перед важными решениями.","fact":"Предсказания дельфийского оракула, по легенде, произносила жрица Пифия, вдыхавшая пары из расщелины в скале.","wiki_en":"Delphi"},{"name":"Колосс Родосский","emoji":"🗿","meta":["Греция","гигантская статуя","построена около 280 г. до н. э."],"description":"Одно из семи чудес древнего мира — огромная бронзовая статуя бога солнца Гелиоса — стояла у входа в гавань острова Родос. Спустя несколько десятилетий после постройки статуя рухнула во время землетрясения и больше не восстанавливалась.","fact":"Вопреки популярным гравюрам, статуя вряд ли стояла, расставив ноги над входом в гавань, — это выдумка более поздних эпох.","wiki_en":"Colossus of Rhodes"},{"name":"Александрийский маяк","emoji":"🗼","meta":["Египет","маяк","построен в III веке до н. э."],"description":"Одно из семи чудес древнего мира возвышалось на острове Фарос у входа в гавань Александрии и веками служило образцом для маяков по всему Средиземноморью. Сооружение постепенно разрушилось от землетрясений в Средние века.","fact":"Маяк был одним из самых высоких сооружений своего времени и много веков оставался в числе высочайших построек, созданных человеком.","wiki_en":"Lighthouse of Alexandria"},{"name":"Висячие сады Семирамиды","emoji":"🌿","meta":["Вавилон, совр. Ирак","легендарные сады","предположительно VI век до н. э."],"description":"Одно из семи чудес древнего мира, описанное античными авторами как ярусные террасы с пышной зеленью посреди засушливой Месопотамии. Археологи до сих пор спорят, существовали ли сады на самом деле и где именно они могли находиться.","fact":"В отличие от других чудес света, точное местонахождение и само существование Висячих садов Семирамиды не подтверждено археологически.","wiki_en":"Hanging Gardens of Babylon"},{"name":"Мавзолей в Галикарнасе","emoji":"🪦","meta":["Турция","гробница-памятник","построен в IV веке до н. э."],"description":"Одно из семи чудес древнего мира — монументальная гробница правителя Мавсола — дала современное слово «мавзолей» для обозначения подобных сооружений. Сооружение простояло более полутора тысяч лет, прежде чем было разрушено землетрясениями.","fact":"Камни разрушенной гробницы позже пошли на постройку рыцарской крепости в Бодруме, стоящей на этом берегу и сегодня.","wiki_en":"Mausoleum at Halicarnassus"},{"name":"Статуя Зевса в Олимпии","emoji":"🗿","meta":["Греция","гигантская статуя","создана в V веке до н. э."],"description":"Одно из семи чудес древнего мира — исполинская статуя верховного греческого бога, покрытая золотом и слоновой костью, — стояла в храме на месте проведения древних Олимпийских игр. Оригинал не сохранился, и судьба статуи после античности остаётся не до конца ясной.","fact":"Статую Зевса в Олимпии создал скульптор Фидий, ранее руководивший работами над скульптурами Парфенона в Афинах.","wiki_en":"Statue of Zeus at Olympia"},{"name":"Храм Артемиды в Эфесе","emoji":"🏛️","meta":["Турция","храм богини Артемиды","построен в VI веке до н. э."],"description":"Одно из семи чудес древнего мира считалось одним из крупнейших храмов античности и несколько раз перестраивалось после пожаров и разрушений. От некогда грандиозного святилища до наших дней дошла лишь одна восстановленная колонна.","fact":"По преданию, храм сжёг человек по имени Герострат — только ради того, чтобы его имя запомнили навсегда.","wiki_en":"Temple of Artemis"},{"name":"Замок Виндзор","emoji":"🏰","meta":["Великобритания","королевская резиденция","основан в XI веке"],"description":"Один из старейших и крупнейших из ныне обитаемых замков мира служит одной из официальных резиденций британских монархов уже почти тысячу лет. Именно здесь похоронена королева Елизавета II.","fact":"Фамилию Виндзор британская королевская семья взяла в 1917 году именно по названию этого замка.","wiki_en":"Windsor Castle"},{"name":"Пирамида Лувра","emoji":"🔺","meta":["Франция","стеклянная пирамида","построена в 1989 году"],"description":"Стеклянно-металлическая пирамида во внутреннем дворе парижского Лувра служит главным входом в музей и когда-то вызывала бурные споры своим современным обликом рядом с историческим дворцом. Сегодня она сама стала одним из узнаваемых символов Парижа.","fact":"Пирамиду спроектировал американский архитектор китайского происхождения Бэй Юймин, а её высота — чуть больше двадцати метров.","wiki_en":"Louvre Pyramid"},{"name":"Вестминстерский дворец","emoji":"🏛️","meta":["Великобритания","здание парламента","нынешнее здание — XIX век"],"description":"Резиденция британского парламента на берегу Темзы была почти полностью перестроена в неоготическом стиле после сильного пожара XIX века. Башня с колоколом Биг-Бен, формально являющаяся лишь частью здания, стала одним из главных символов Лондона.","fact":"Знаменитый Биг-Бен — это название колокола на башне Вестминстерского дворца, а не самой башни, как принято думать.","wiki_en":"Palace of Westminster"}];
